import{_ as n,l,o as e,c as r,v as i,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"原生分辨率 ViT","description":"","frontmatter":{"title":"原生分辨率 ViT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/native-resolution-vit.md","filePath":"llm/native-resolution-vit.md","lastUpdated":1789023840000}'),m={name:"llm/native-resolution-vit.md"};function c(_,a,T,u,V,E){const o=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="原生分辨率-vit" tabindex="-1">原生分辨率 ViT <a class="header-anchor" href="#原生分辨率-vit" aria-label="Permalink to &quot;原生分辨率 ViT&quot;">​</a></h1><div class="epigraph"><p>把任意高宽的图 squish 到 224 方形，表格与路牌先死在编码器里。位置编码与切块必须承认二维可变网格。</p><footer>—— Dehghani 等 NaViT；动态分辨率实践见 [Qwen2-VL](/llm/qwen-vl-naive-dynamic-res) 与 [AnyRes](/llm/anyres)</footer></div><p><a href="/llm/continuous-vs-discrete-vision-tokens">上一课</a>选定理解侧走连续 patch。主干 ViT 课已写固定边长的位置嵌入。本课写原生分辨率：可变 \\(H,W\\)，token 数随图变。缺口是画布假设。后课 2D RoPE 提供位置编码的一种实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分类 ViT 假设固定 \\(N\\)。VLM 要读文档、屏幕、非方形照片。强制 resize 破坏长宽比；padding 浪费上下文。AnyRes 把图切成多块分别过固定 ViT，再拼接——分辨率来自拼块，位置关系要另编码。NaViT 在同一 ViT 里对可变序列做打包训练，补位与掩码处理不同 \\(N\\)。Qwen2-VL 一类动态分辨率把原生切块 + 二维位置做成产品默认。</p><p>token 税：\\(N\\approx HW/P^2\\) 直接占 LLM 上下文，必须与<a href="/llm/vision-token-compression">视觉 token 压缩</a>一起预算。</p><p><span class="marginnote">原生分辨率不是无限分辨率。仍有上限 \\(N_{\\max}\\)，超大图要切页或降采样，只是不再强行方形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现清单：可变长注意力掩码；二维位置（下一课）；打包多个不同分辨率图进同一批（NaViT 的效率点）；与 LLM 的接口声明最大视觉 token。评测用文档 OCR、截图、非方形图，不用只 squish 过的 ImageNet。</p>',9)),(e(),s(p,null,{default:t(()=>[h(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E4%BB%BB%E6%84%8F%20H%20x%20W%22%5D%20--%3E%20PATCH%5B%22P%20x%20P%20%E5%88%87%E5%9D%97%22%5D%0A%20%20PATCH%20--%3E%20POS%5B%22%E4%BA%8C%E7%BB%B4%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20VIT%5B%22%E5%8F%AF%E5%8F%98%E9%95%BF%20ViT%22%5D%0A%20%20VIT%20--%3E%20N%5B%22N%20%E4%B8%AA%E8%BF%9E%E7%BB%AD%20token%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定位置嵌入把第 \\(i\\) 个 token 当成「224 画布上的第 \\(i\\) 格」。分辨率一变，格的物理意义变了，插值只是权宜。原生网格让格子对应真实 patch 坐标，注意力才能学到「右上角表头」。打包训练迫使模型在不同 \\(N\\) 上共享权重，避免只在 224 上过拟合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可变 \\(N\\) 让 KV 缓存与编译形状变难，服务要动态分桶。下一课把二维相对位置写成 RoPE 的推广。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原生分辨率保留长宽比与表格结构，token 数随图变。</li><li>必须配二维位置与可变长掩码；有 \\(N_{\\max}\\)。</li><li>用文档与截图评测，不用 squish 分类榜。</li><li>出处：Dehghani 等 NaViT；AnyRes；Qwen2-VL 动态分辨率。</li></ul>',6))])}const f=n(m,[["render",c]]);export{A as __pageData,f as default};
